 /// 提出時のユーザーの TZ での日付。Prisma では UTC の 0 時の Date で返るので、Repository で toISOString().slice(0, 10) にする\n  studyDate            DateTime? @map(\"study_date\") @db.Date\n  createdAt            DateTime  @default(now()) @map(\"created_at\")\n  updatedAt            DateTime  @updatedAt @map(\"updated_at\")\n\n  user        User                @relation(fields: [userId], references: [id], onDelete: Cascade)\n  passage     Passage             @relation(fields: [passageId], references: [id], onDelete: Restrict)\n  answers     AttemptAnswer[]\n  wordLookups AttemptWordLookup[]\n\n  @@index([userId, studyDate])\n  @@index([userId, passageId])\n  @@map(\"reading_attempts\")\n}\n\n// 取得した文書（GitHub のファイル / サイトのページ）。取得方法ごとの列は nullable\nmodel SourceDocument {\n  id             Int       @id @default(autoincrement())\n  sourceId       Int       @map(\"source_id\")\n  /// GitHub はリポジトリ内のファイルパス、サイトは URL のパス\n  path           String\n  title          String?\n  /// NULL は未取得\n  fetchedAt      DateTime? @map(\"fetched_at\")\n  contentHash    String?   @map(\"content_hash\")\n  /// GitHub のみ\n  blobSha        String?   @map(\"blob_sha\")\n  /// GitHub のみ\n  commitSha      String?   @map(\"commit_sha\")\n  /// サイトのみ\n  etag           String?\n  /// サイトのみ。Last-Modified ヘッダの値\n  lastModified   String?   @map(\"last_modified\")\n  /// サイトのみ\n  sitemapLastmod DateTime? @map(\"sitemap_lastmod\")\n  /// サイトのみ\n  httpStatus     Int?      @map(\"http_status\") @db.SmallInt\n  createdAt      DateTime  @default(now()) @map(\"created_at\")\n  updatedAt      DateTime  @updatedAt @map(\"updated_at\")\n\n  source   ContentSource @relation(fields: [sourceId], references: [id], onDelete: Restrict)\n  passages Passage[]\n\n  @@unique([sourceId, path])\n  @@index([sourceId, fetchedAt])\n  @@map(\"source_documents\")\n}\n\n// ユーザー（認証プロバイダー非依存）\nmodel User {\n  id        Int      @id @default(autoincrement())\n  email     String?  @unique\n  name      String?\n  avatarUrl String?  @map(\"avatar_url\")\n  /// I